 #include "webserver/auth/auth.hpp"

+#include <algorithm>
+#include <fstream>
 #include <string>
+#include <string_view>
+
+namespace {
+constexpr char comment_prefix = '#';
+
+std::string_view trim(std::string_view s) {
+    while (!s.empty() && (s.front() == ' ' || s.front() == '\t' || s.front() == '\r')) {
+        s.remove_prefix(1);
+    }
+    while (!s.empty() && (s.back() == ' ' || s.back() == '\t' || s.back() == '\r')) {
+        s.remove_suffix(1);
+    }
+    return s;
+}
+
+bool split_user_line(std::string_view line, std::string_view& username, std::string_view& password) {
+    line = trim(line);
+    if (line.empty() || line.front() == comment_prefix) {
+        return false;
+    }
+
+    auto sep = line.find_first_of(" \t");
+    if (sep == std::string_view::npos) {
+        return false;
+    }
+
+    username = trim(line.substr(0, sep));
+    password = trim(line.substr(sep + 1));
+    return !username.empty() && !password.empty();
+}
+
+bool constant_time_equal(std::string_view a, std::string_view b) {
+    auto diff = static_cast<unsigned char>(a.size() ^ b.size());
+    const auto max_size = std::max(a.size(), b.size());
+
+    for (size_t i = 0; i < max_size; ++i) {
+        const auto ac = i < a.size() ? static_cast<unsigned char>(a[i]) : 0;
+        const auto bc = i < b.size() ? static_cast<unsigned char>(b[i]) : 0;
+        diff |= static_cast<unsigned char>(ac ^ bc);
+    }
+
+    return diff == 0;
+}
+}  // namespace

 Authenticator::Authenticator(const std::string& p) : file_path(p) {}

 Authenticator::~Authenticator() { wipe(buffer.data(), buffer.size()); }
+
+bool Authenticator::auth(const std::string& username, std::string& password) {
+    std::ifstream file{ file_path };
+    if (!file) {
+        wipe(password.data(), password.size());
+        password.clear();
+        return false;
+    }
+
+    bool ok = false;
+    std::string line;
+    while (std::getline(file, line)) {
+        std::string_view stored_username;
+        std::string_view stored_password;
+        if (!split_user_line(line, stored_username, stored_password)) {
+            continue;
+        }
+        if (stored_username != username || stored_password.size() > buffer.size()) {
+            continue;
+        }
+
+        std::fill(buffer.begin(), buffer.end(), '\0');
+        std::copy(stored_password.begin(), stored_password.end(), buffer.begin());
+        ok = constant_time_equal(
+            std::string_view{ buffer.data(), stored_password.size() }, password);
+        break;
+    }
+
+    wipe(buffer.data(), buffer.size());
+    wipe(password.data(), password.size());
+    password.clear();
+    return ok;
+}
