#include <array>
#include <cstddef>
#include <cstring>
#include <fstream>
#include <limits>
#include <string>

#if defined(_WIN32)
#define NOMINMAX
#include <windows.h>
#elif defined(__linux__) || defined(__APPLE__) || defined(__FreeBSD__)
#include <strings.h>
#endif

class Authenticator {
public:
    explicit Authenticator(std::string filePath)
        : filePath_(std::move(filePath)) {
    }

    ~Authenticator() {
        wipe(record_.data(), record_.size());
    }

    Authenticator(const Authenticator&) = delete;
    Authenticator& operator=(const Authenticator&) = delete;

    bool authenticate(const std::string& username,
                      std::string& password) {
        bool authenticated = false;

        std::ifstream file(filePath_, std::ios::binary);

        if (file) {
            while (readRecord(file)) {
                char* separator = std::strchr(record_.data(), ':');

                if (separator == nullptr) {
                    wipe(record_.data(), record_.size());
                    continue;
                }

                // "lain:hello123" 变为 "lain\0hello123"
                *separator = '\0';

                const char* storedUsername = record_.data();
                const char* storedPassword = separator + 1;

                if (username == storedUsername) {
                    authenticated = (password == storedPassword);

                    wipe(record_.data(), record_.size());
                    break;
                }

                wipe(record_.data(), record_.size());
            }
        }

        wipe(record_.data(), record_.size());

        // 先覆盖密码字符，再清空 string 的逻辑长度。
        wipePassword(password);

        return authenticated;
    }

private:
    std::string filePath_;
    std::array<char, 256> record_{};

    bool readRecord(std::ifstream& file) {
        wipe(record_.data(), record_.size());

        if (file.getline(record_.data(),
                         static_cast<std::streamsize>(record_.size()))) {
            removeCarriageReturn();
            return true;
        }

        if (!file.eof()) {
            // 当前行过长，丢弃其余部分。
            file.clear();
            file.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        }

        return false;
    }

    void removeCarriageReturn() noexcept {
        const std::size_t length = std::strlen(record_.data());

        if (length > 0 && record_[length - 1] == '\r') {
            record_[length - 1] = '\0';
        }
    }

    static void wipePassword(std::string& password) noexcept {
        if (!password.empty()) {
            wipe(password.data(), password.size());
        }

        password.clear();
    }

    static void wipe(void* memory, std::size_t size) noexcept {
#if defined(_WIN32)
        ::SecureZeroMemory(memory, size);
#elif defined(__linux__) || defined(__APPLE__) || defined(__FreeBSD__)
        ::explicit_bzero(memory, size);
#else
        volatile unsigned char* p =
            static_cast<volatile unsigned char*>(memory);

        while (size-- > 0) {
            *p++ = 0;
        }
#endif
    }
};  参考这个实现, 而不是使用 string, 无法确保 string  在内存中会被自动销毁

